class Solution:
    def maxFrequency(self, nums, k):
        cnt_k = nums.count(k)
        best = 0
        for v in set(nums):
            if v == k:
                continue
            cur = 0
            for x in nums:
                if x == v:
                    cur += 1
                elif x == k:
                    cur -= 1
                if cur < 0:
                    cur = 0
                if cur > best:
                    best = cur
        return cnt_k + best
